CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.workspace_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, entity text NOT NULL CHECK(entity IN ('Agent','ApprovalRule','BioLearning','Conversation','EngineKey','MealLog','MemoryNote','Message','RehabProtocol','Routine','SyncJob','AgentAction','WaitlistSignup')), data jsonb NOT NULL DEFAULT '{}'::jsonb, original_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity,original_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workspace_records TO authenticated;
GRANT ALL ON public.workspace_records TO service_role;
ALTER TABLE public.workspace_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_read ON public.workspace_records FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY records_insert ON public.workspace_records FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND entity NOT IN ('Message','AgentAction','EngineKey'));
CREATE POLICY records_update ON public.workspace_records FOR UPDATE TO authenticated USING((owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) AND entity NOT IN ('Message','AgentAction','EngineKey')) WITH CHECK((owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) AND entity NOT IN ('Message','AgentAction','EngineKey'));
CREATE POLICY records_delete ON public.workspace_records FOR DELETE TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX workspace_owner_entity ON public.workspace_records(owner_id,entity,updated_at DESC);
CREATE INDEX workspace_conversation_messages ON public.workspace_records((data->>'conversation_id')) WHERE entity='Message';
CREATE FUNCTION public.touch_workspace_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.owner_id<>OLD.owner_id OR NEW.entity<>OLD.entity THEN RAISE EXCEPTION 'Ownership and entity cannot change'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER touch_workspace_record BEFORE UPDATE ON public.workspace_records FOR EACH ROW EXECUTE FUNCTION public.touch_workspace_record();
CREATE TABLE public.account_preferences(user_id uuid PRIMARY KEY, marketing_consent boolean NOT NULL DEFAULT false, theme text NOT NULL DEFAULT 'light' CHECK(theme IN ('light','dark')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.account_preferences TO authenticated;
GRANT ALL ON public.account_preferences TO service_role;
ALTER TABLE public.account_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_preferences ON public.account_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.migration_identities(original_user_id text PRIMARY KEY,email text NOT NULL UNIQUE, auth_user_id uuid UNIQUE, verified_at timestamptz, profile_data jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT ALL ON public.migration_identities TO service_role;
ALTER TABLE public.migration_identities ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.execution_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL, record_id uuid NOT NULL REFERENCES public.workspace_records(id) ON DELETE CASCADE, request_id uuid NOT NULL, status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','completed','failed','unknown')), result text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,request_id));
GRANT SELECT ON public.execution_runs TO authenticated;
GRANT ALL ON public.execution_runs TO service_role;
ALTER TABLE public.execution_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_runs ON public.execution_runs FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE INDEX execution_runs_record ON public.execution_runs(record_id);
CREATE FUNCTION public.assign_default_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user') ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER assign_workspace_role AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_default_role();